/* geteuid_override.c */
/* A simple shared library that overrides the standard geteuid function */

#define _GNU_SOURCE
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>

// Store the original function pointer
static uid_t (*original_geteuid)(void) = NULL;

// Custom geteuid implementation
uid_t geteuid(void) {
    // Initialize the original function pointer if not already done
    if (original_geteuid == NULL) {
        // Use dlsym with RTLD_NEXT to get the next occurrence of the symbol
        original_geteuid = (uid_t (*)(void)) dlsym(RTLD_NEXT, "geteuid");

        // Fallback: if dlsym fails, we'll just return a default value
        if (original_geteuid == NULL) {
            fprintf(stderr, "Warning: Could not find original geteuid function\n");
            return 1000; // Return a common non-root UID as fallback
        }
    }

    // You can customize this return value as needed
    // For demonstration, we'll return a fixed UID (e.g., 1000)
    // In a real scenario, you might want to check an environment variable
    // or some other condition

    // Check for OVERRIDE_EUID environment variable
    const char *override_str = getenv("OVERRIDE_EUID");
    if (override_str != NULL) {
        return (uid_t) atoi(override_str);
    }

    // Default overridden value
    return 1000;
}
